<script lang="ts">import VocabularyForm from '$lib/components/VocabularyForm.svelte'; let { data, form } = $props(); function confirmDelete(e: SubmitEvent) { if (!confirm('Delete this vocabulary entry?')) e.preventDefault(); }</script>
<div class="page-shell form-page"><a class="back" href={`/sessions/${data.session.id}`}>Back to {data.session.title}</a><section class="panel"><p class="eyebrow">Edit word</p><h1>{data.entry.vocabulary}</h1><form method="POST" action="?/update"><VocabularyForm values={form?.values ?? data.entry} errors={form?.errors} submitLabel="Save vocabulary" /></form><form method="POST" action="?/delete" onsubmit={confirmDelete}><input type="hidden" name="confirmation" value="delete" /><button class="danger" type="submit">Delete vocabulary</button></form></section></div>
